import {createRecorder,PERF_TARGET_MS} from './perf-metrics.mjs';
// Loaded only by the exact ?perf=1 opt-in. No network writes or public QA hooks.
export function installPerfExporter({B,scene,engine,build,snapshot,readyMs}){
 const panel=document.createElement('section');panel.id='perf-panel';panel.dir='rtl';panel.style.cssText='position:fixed;top:8px;left:8px;z-index:10000;background:#14251feb;color:#fff;padding:10px;border:1px solid #d5b66d;border-radius:8px;max-width:300px;font:13px sans-serif';
 const label=document.createElement('label');label.textContent='قياس جهازك · ٥ دقائق لعب فعلي ';
 const device=document.createElement('input');device.placeholder='اسم الهاتف (اختياري)';device.setAttribute('aria-label','اسم الهاتف');label.append(device);
 const start=document.createElement('button');start.id='perf-start';start.textContent='ابدأ القياس';
 const exportButton=document.createElement('button');exportButton.id='perf-export';exportButton.textContent='إيقاف وتصدير JSON';exportButton.disabled=true;
 const status=document.createElement('div');status.id='perf-status';status.textContent='ابدأ اللعب ثم سجّل. فتح القوائم وإخفاء الصفحة يوقفان العدّ.';panel.append(label,start,exportButton,status);document.body.append(panel);
 let recorder=null,instrumentation=null,observer=null,latest=null,lastStatus=0,texturePeak=0;
 function textureEstimate(){const seen=new Set();let bytes=0;for(const t of scene.textures){const i=t.getInternalTexture();if(!i||seen.has(i))continue;seen.add(i);bytes+=(i.width||0)*(i.height||0)*4*(i.generateMipMaps?4/3:1)*(i.isCube?6:1);}return bytes/1048576;}
 function finish(){if(!recorder)return;scene.onAfterRenderObservable.remove(observer);observer=null;instrumentation?.dispose();instrumentation=null;const stats=recorder.report();const resources=performance.getEntriesByType('resource');latest={schema:'shire-perf-v1',createdAt:new Date().toISOString(),build,deviceLabel:device.value.trim(),userAgent:navigator.userAgent,platform:navigator.platform,automatedBrowser:!!navigator.webdriver,gpu:engine.getGlInfo(),renderSize:{width:engine.getRenderWidth(),height:engine.getRenderHeight()},load:{bootReadyMs:readyMs,networkEncodedBytes:resources.reduce((n,r)=>n+(r.encodedBodySize||0),0),resourcesWithoutByteSizes:resources.filter(r=>!r.encodedBodySize).length},...stats,textureEstimatedMB:{end:textureEstimate(),peak:texturePeak,method:'Unique internal texture dimensions, RGBA8 assumption, mipmaps and cubemap faces. Estimate; compressed/HDR/render-target allocation may differ.'},definitions:{medianFPS:'1000 / median real frame interval ms',p05FPS:'1000 / p95 real frame interval ms',slowestFivePercentFPS:'1000 / mean slowest ceil(5% frames) interval',activeTime:'Visible, started gameplay; excludes menus, dialogue and cinematics. No delta clamp or long-frame filtering.',triangles:'scene.getActiveIndices()/3 including active instances; rendered geometry estimate',drawCalls:'SceneInstrumentation.drawCallsCounter.current',qualification:'CI/SwiftShader is never physical owner-phone performance. Device label is user supplied; no G4 approval implied.'}};recorder=null;start.disabled=false;status.textContent=stats.completed?'اكتمل التسجيل · حمّل JSON':'تسجيل جزئي؛ لا يُعد قياس خمس دقائق';download();}
 function download(){if(!latest)return;const url=URL.createObjectURL(new Blob([JSON.stringify(latest,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='shire-perf-'+(build.commit||'local').slice(0,12)+'-'+Date.now()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
 start.onclick=()=>{recorder=createRecorder();latest=null;texturePeak=textureEstimate();instrumentation=new B.SceneInstrumentation(scene);start.disabled=true;exportButton.disabled=false;observer=scene.onAfterRenderObservable.add(()=>{const s=snapshot(),eligible=!document.hidden&&s.started&&!s.activeNPC&&!s.journalOpen&&!s.mapOpen&&!s.cinematic.active&&!s.party.active&&!s.journey.active;const now=performance.now();recorder.tick(now,eligible,instrumentation.drawCallsCounter.current,scene.getActiveIndices()/3);if(now-lastStatus>1000){lastStatus=now;texturePeak=Math.max(texturePeak,textureEstimate());status.textContent=Math.floor(recorder.elapsedMs/1000)+' / '+PERF_TARGET_MS/1000+' ثانية لعب';}if(recorder.done)finish();});};
 exportButton.onclick=()=>recorder?finish():download();document.addEventListener('visibilitychange',()=>recorder?.pause());
}
